const inflight = new Map();

function load(key, fetchValue) {
  const existing = inflight.get(key);
  if (existing) return existing;                 // join the flight
  const p = fetchValue(key).finally(() => inflight.delete(key));  // forget
  inflight.set(key, p);                          // announced before any await
  return p;
}

